- **Frontend:** HTML (19%)
- **Containerization:** Docker (2.7%)

## Core Features

### Python Backend Implementation
```python
# Razorpay payment creation
import razorpay

client = razorpay.Client(auth=(RAZORPAY_KEY, RAZORPAY_SECRET))

def create_payment_order(amount, customer_email, product_id):
    """Create Razorpay order"""
    order_data = {
        'amount': int(amount * 100),  # Amount in paise
        'currency': 'INR',
        'receipt': f'order_{product_id}',
        'payment_capture': 1,  # Auto-capture
        'notes': {
            'customer_email': customer_email,
            'product_id': product_id
        }
    }

    response = client.order.create(data=order_data)
    return response

# Verify payment signature
def verify_payment(razorpay_order_id, razorpay_payment_id, razorpay_signature):
    """Verify Razorpay signature"""
    params_dict = {
        'razorpay_order_id': razorpay_order_id,
        'razorpay_payment_id': razorpay_payment_id,
        'razorpay_signature': razorpay_signature
    }

    try:
        client.utility.verify_payment_signature(params_dict)
        return True
    except:
        return False

# Handle payment webhook
@app.route('/webhook/razorpay', methods=['POST'])
def razorpay_webhook():
    data = request.json

    if data['event'] == 'payment.authorized':
        payment_id = data['payload']['payment']['entity']['id']
        order_id = data['payload']['payment']['entity']['order_id']

        # Mark order as paid in database
        update_order_status(order_id, 'completed', payment_id)

    return jsonify({'status': 'ok'})
```

