          razorpay_payment_id: response.razorpay_payment_id,
          razorpay_signature: response.razorpay_signature
        })
      })
    }
  };

  const razorpay = new Razorpay(options);
  razorpay.open();
}
</script>
```

## EXTENSIVE OVERVIEW
A sophisticated AI-powered knowledge system built with Laravel 10 for managing Vedic knowledge, providing personalized astrological recommendations, and intelligent conversational responses about Rudraksha products and spiritual topics.

## Tech Stack
